package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLI_ArgumentParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantCode   int
		wantStderr string
	}{
		{"no args", []string{}, 2, "Usage:"},
		{"unknown command", []string{"bogus"}, 2, "unknown command"},
		{"get without key", []string{"get"}, 2, "requires a key"},
		{"set without value", []string{"set", "foo"}, 2, "requires key and value"},
		{"delete without key", []string{"delete"}, 2, "requires a key"},
		{"flags only no command", []string{"--quiet", "--verbose"}, 2, "no command specified"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			cli := NewCLI(stdout, stderr, t.TempDir())

			code := cli.Run(tt.args)

			if code != tt.wantCode {
				t.Errorf("exit code = %d, want %d", code, tt.wantCode)
			}
			if !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestCLI_Init(t *testing.T) {
	t.Run("creates new config", func(t *testing.T) {
		tmpDir := t.TempDir()
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, tmpDir)

		code := cli.Run([]string{"init"})

		if code != 0 {
			t.Fatalf("exit code = %d, want 0; stderr: %s", code, stderr.String())
		}
		if _, err := os.Stat(filepath.Join(tmpDir, "config.yaml")); err != nil {
			t.Error("config file not created")
		}
	})

	t.Run("fails if exists", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "config.yaml")
		os.WriteFile(configPath, []byte("existing: true"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, tmpDir)

		code := cli.Run([]string{"init"})

		if code != 1 {
			t.Errorf("exit code = %d, want 1", code)
		}
		if !bytes.Contains(stderr.Bytes(), []byte("already exists")) {
			t.Error("expected 'already exists' error")
		}
	})

	t.Run("quiet suppresses output", func(t *testing.T) {
		tmpDir := t.TempDir()
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, tmpDir)

		cli.Run([]string{"--quiet", "init"})

		if stdout.Len() != 0 {
			t.Errorf("stdout should be empty with --quiet, got %q", stdout.String())
		}
	})
}

func TestCLI_GetSetDelete(t *testing.T) {
	tmpDir := t.TempDir()
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	cli := NewCLI(stdout, stderr, tmpDir)

	// Set creates value
	if code := cli.Run([]string{"set", "mykey", "myvalue"}); code != 0 {
		t.Fatalf("set failed: %s", stderr.String())
	}

	// Get retrieves it
	stdout.Reset()
	if code := cli.Run([]string{"get", "mykey"}); code != 0 {
		t.Fatalf("get failed: %s", stderr.String())
	}
	if got := stdout.String(); got != "myvalue\n" {
		t.Errorf("get = %q, want %q", got, "myvalue\n")
	}

	// Delete removes it
	if code := cli.Run([]string{"delete", "mykey"}); code != 0 {
		t.Fatalf("delete failed: %s", stderr.String())
	}

	// Get now fails
	stderr.Reset()
	if code := cli.Run([]string{"get", "mykey"}); code != 1 {
		t.Error("get should fail after delete")
	}
}

func TestCLI_Validate(t *testing.T) {
	t.Run("valid yaml", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "config.yaml")
		os.WriteFile(configPath, []byte("key: value\n"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, tmpDir)

		if code := cli.Run([]string{"validate"}); code != 0 {
			t.Errorf("validate failed: %s", stderr.String())
		}
		if !bytes.Contains(stdout.Bytes(), []byte("valid")) {
			t.Error("expected 'valid' in output")
		}
	})

	t.Run("invalid yaml", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "config.yaml")
		os.WriteFile(configPath, []byte(":::invalid:::\n  bad indent"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, tmpDir)

		if code := cli.Run([]string{"validate"}); code != 1 {
			t.Error("validate should fail on invalid yaml")
		}
		if !bytes.Contains(stderr.Bytes(), []byte("invalid YAML")) {
			t.Errorf("stderr = %q, want YAML error", stderr.String())
		}
	})
}

func TestCLI_OutputFormats(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")
	os.WriteFile(configPath, []byte("foo: bar\n"), 0644)

	formats := []struct {
		format   string
		contains string
	}{
		{"json", `"foo"`},
		{"yaml", "foo:"},
		{"text", "foo:"},
	}

	for _, f := range formats {
		t.Run(f.format, func(t *testing.T) {
			stdout := &bytes.Buffer{}
			cli := NewCLI(stdout, &bytes.Buffer{}, tmpDir)

			cli.Run([]string{"--format", f.format, "list"})

			if !bytes.Contains(stdout.Bytes(), []byte(f.contains)) {
				t.Errorf("%s output = %q, want containing %q", f.format, stdout.String(), f.contains)
			}
		})
	}
}

func TestCLI_MissingFile(t *testing.T) {
	tmpDir := t.TempDir()
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	cli := NewCLI(stdout, stderr, tmpDir)

	code := cli.Run([]string{"get", "anything"})

	if code != 1 {
		t.Errorf("exit code = %d, want 1", code)
	}
	if !bytes.Contains(stderr.Bytes(), []byte("Error")) {
		t.Error("expected error message on stderr")
	}
	if stdout.Len() != 0 {
		t.Error("errors should go to stderr, not stdout")
	}
}
